            "fr": "PASCAL (relevant la tête, les yeux embués de larmes) : La solitude de l'homme devant son choix suprême... C'est là que réside le véritable <span class='term' data-term='mystere'>mystère ontologique</span>. Ni les amis ni les censeurs ne peuvent pénétrer ce sanctuaire secret où l'âme tranche son propre destin.",
            "en": "PASCAL (raising his head, his eyes misted with tears): The solitude of a man before his supreme choice... That is where the true <span class='term' data-term='mystere'>ontological mystery</span> resides. Neither friends nor censors can enter that secret sanctuary where the soul determines its own destiny."
