            "fr": "JACQUELINE (d'une voix grave et limpide) : La France restera fidèle à sa vocation, monsieur Launoy, même si elle doit traverser la nuit des épreuves. La jeunesse d'aujourd'hui sait que la liberté ne s'octroie pas : elle se conquiert par le sacrifice.",
            "en": "JACQUELINE (in a deep and limpid voice): France will remain faithful to her vocation, Monsieur Launoy, even if she must traverse the night of trials. Today's youth knows that freedom is not granted: it is conquered through sacrifice."
